wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

fn civil_from_days(days: i64) -> (i64, i64, i64) {
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    if m <= 2 {
        y += 1;
    }
    (y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = crate::wasi::clocks::wall_clock::now();
        let days = (now.seconds / 86_400) as i64;
        let (mut y, m, d) = civil_from_days(days);
        // Keep the date at exactly 10 characters (YYYY-MM-DD).
        if y > 9999 {
            y = 9999;
        }
        if y < 0 {
            y = 0;
        }
        RunInfo {
            date: format!("{:04}-{:02}-{:02}", y, m, d),
            started: now.seconds,
        }
    }
}

export!(Node);
